#include "runtime/interpreter.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
int main(){using namespace penta;unsigned checks=0,failures=0;runtime::ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/("penta-fem-system-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));options.odeCacheDirectory=options.dataDirectory/"cache/odes";options.maxOperations=100000000;std::filesystem::create_directories(options.dataDirectory);auto run=[&](const std::string& source){++checks;const auto result=runtime::execute(source,{},options);if(!result.ok()){++failures;for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';}};
run("native function [real x,real y] plane(real u,real v){return u,v;}native function real reaction(real u,real x,real y){return u*u*u;}native function real forcing(real x,real y,real scale){real u=scale*x*(1-x)*y*(1-y);return 2*scale*(x*(1-x)+y*(1-y))+u*u*u;}native function real exact(real x,real y,real scale){return scale*x*(1-x)*y*(1-y);}record mesh=paramesh(plane,linspace(0,1,3),linspace(0,1,3));record a=femsystem(reaction,mesh,options(order=4,forcing=forcing,forcing_parameters=options(scale=1.0),exact=exact,exact_parameters=options(scale=1.0)));record b=femsystem(reaction,mesh,options(order=4,forcing=forcing,forcing_parameters=options(scale=2.0),exact=exact,exact_parameters=options(scale=2.0)));assert(a.converged&&b.converged);assert(a.l2_error<1e-8&&b.l2_error<1e-8);assert(a.jacobian_evaluations>0);assert(a.cache_keys==b.cache_keys&&b.cache_hit);assert(size(a.dof_values,2)==1);assert(length(a.vertex_dofs)==9);figure(1);femsystemplot(a);");
run("algebra H=builtin_algebra(\"quaternion\");native function [real x,real y] plane(real u,real v){return u,v;}native function element<H> reaction(element<H> q,real x,real y){return q*q*q;}native function element<H> exact(real x,real y){return 1+.1*H.i+.2*H.j;}native function element<H> forcing(real x,real y){element<H> q=1+.1*H.i+.2*H.j;return q*q*q;}record mesh=paramesh(plane,linspace(0,1,3),linspace(0,1,3));record a=femsystem(reaction,mesh,options(order=2,forcing=forcing,boundary_value=exact,exact=exact,diffusion=1+.05*H.i));assert(a.converged);assert(a.components==4);assert(a.l2_error<1e-8);assert(norm(a.dof_values(:,4),\"fro\")<1e-8);assert(a.algebra_hash==algebra_info(H).hash);");
run("native function [real x,real y] plane(real u,real v){return u,v;}native function real reaction(real u,real x,real y){return 0.0;}native function real boundary(real tag,real x,real y,real nx,real ny){return nx+ny+2*(x+y);}record mesh=paramesh(plane,linspace(0,1,3),linspace(0,1,3));record a=femsystem(reaction,mesh,options(boundary=\"robin\",boundary_value=boundary,boundary_signature=\"tag_normal\",robin_alpha=2.0,allow_unanchored=1));assert(a.converged);assert(norm(a.dof_values-a.dof_coordinates(:,1)-a.dof_coordinates(:,2),\"fro\")<1e-8);");
#ifdef PENTA_SOURCE_DIR
for(const auto* name:{"native-nonlinear-p4.p","pentarnion-nonlinear-h1.p","native-curved-surface.p"}){std::ifstream input(std::filesystem::path(PENTA_SOURCE_DIR)/"examples/high-order-finite-elements"/name);run(std::string((std::istreambuf_iterator<char>(input)),{}));}
#endif
std::error_code ignored;std::filesystem::remove_all(options.dataDirectory,ignored);std::cout<<checks<<" nonlinear FEM language checks, "<<failures<<" failures\n";return failures?1:0;}
